import Foundation

// Natural Earth 1:110m low-resolution country polygons, dissolved into land.
// Public domain. Coordinates quantized to 0.01 degrees; no political borders.
// Each triangle has three (latitude, longitude) Int16 little-endian pairs.
enum IumrahHemisphereLandData {
    static let triangles: [IumrahHemisphereProjection.Triangle] = {
        guard let data = Data(base64Encoded: encoded, options: .ignoreUnknownCharacters),
              data.count.isMultiple(of: 12) else { return [] }
        let bytes = [UInt8](data)
        func degrees(_ offset: Int) -> Double {
            let raw = UInt16(bytes[offset]) | (UInt16(bytes[offset + 1]) << 8)
            return Double(Int16(bitPattern: raw)) / 100
        }
        func vertex(_ offset: Int) -> IumrahHemisphereProjection.Vector {
            .init(latitude: degrees(offset), longitude: degrees(offset + 2))
        }
        return stride(from: 0, to: bytes.count, by: 12).map { offset in
            .init(a: vertex(offset), b: vertex(offset + 4), c: vertex(offset + 8))
        }
    }()

